	{ // "7.2"
		_res = db.Exec("\n  CREATE VIRTUAL TABLE c\n    USING transitive_closure(idcolumn='abc'x, tablename='t', parentcolumn='p');\n")
		if _res.Error != nil {
			t.Errorf("exec error: %v\n  sql: %s", _res.Error, "\n  CREATE VIRTUAL TABLE c\n    USING transitive_closure(idcolumn='abc'x, tablename='t', parentcolumn='p');\n")
		}
	}
	{ // "7.3"
		r = db.Query("\n  SELECT * FROM c WHERE root=1;\n")
		if r.Error != nil {
			t.Errorf("query error: %v\n  sql: %s", r.Error, "\n  SELECT * FROM c WHERE root=1;\n")
			return
		}
		got := flatten(r)
		want := "1 0 2 1"
		if got != want {
			t.Errorf("result mismatch\n  got:  [%s]\n  want: [%s]", got, want)
		}
	}
